 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(comp)

    for comp in components:
        r0 = min(r for r, c in comp)
        r1 = max(r for r, c in comp)
        c0 = min(c for r, c in comp)
        c1 = max(c for r, c in comp)
        # A rectangular frame with a one-cell opening in its top edge.
        openings = [c for c in range(c0 + 1, c1) if grid[r0][c] == 0]
        if len(openings) != 1 or r0 == 0:
            continue
        hole = openings[0]
        if not all(grid[r][c0] == 5 and grid[r][c1] == 5 for r in range(r0, r1 + 1)):
            continue
        if not all(grid[r1][c] == 5 for c in range(c0, c1 + 1)):
            continue
        # Fill the frame's interior and its opening.
        for c in range(c0 + 1, c1):
            out[r0][c] = 2
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                out[r][c] = 2
        # Extend from the opening across the row above the frame, away from its center.
        if hole >= (c0 + c1) / 2:
            for c in range(0, hole + 1):
                out[r0 - 1][c] = 2
        else:
            for c in range(hole, w):
                out[r0 - 1][c] = 2
    return out
